# Input palette.
_BG, _BLUE, _RED, _YELLOW, _TEAL = 0, 1, 2, 4, 8
_REQUIRED_INPUT_COLORS = {_BG, _BLUE, _RED, _TEAL}

# Canvas and source rectangle bounds.
_GRID_HEIGHT = 19
_GRID_WIDTH_RANGE = (18, 19)
_SOURCE_SIZE_RANGE = (4, 7)
_SOURCE_EDGE_GAP, _SOURCE_MAX_TOP, _SOURCE_CENTER_JITTER = 4, 7, 2

# Object separation and blocker rectangle bounds.
_MIN_OBJECT_GAP, _RAY_OBJECT_GAP = 1, 1
_BLOCKER_COUNT_RANGE = (1, 4)
_BLOCKER_HEIGHTS = range(2, 9)
_BLOCKER_WIDTHS = range(2, 10)

# Passthrough red rectangle bounds.
_RED_COUNT_RANGE = (2, 6)
_RED_PATH_COUNT_MIN = 1
_RED_HEIGHTS = range(2, 7)
_RED_WIDTHS = range(2, 14)

# Retry budget for valid oracle-checked samples.
_MAX_GENERATION_ATTEMPTS = 300


def _fits(rect, rects, H, W):
    r0, c0, r1, c1 = rect
    if r0 < 0 or c0 < 0 or r1 >= H or c1 >= W:
        return False
    for or0, oc0, or1, oc1 in rects:
        if not (
            r1 < or0 - _MIN_OBJECT_GAP
            or r0 > or1 + _MIN_OBJECT_GAP
            or c1 < oc0 - _MIN_OBJECT_GAP
            or c0 > oc1 + _MIN_OBJECT_GAP
        ):
            return False
    return True


def _place(grid, rect, color):
    r0, c0, r1, c1 = rect
    patch = np.full((r1 - r0 + 1, c1 - c0 + 1), color, dtype=int)
    paste(grid, patch, r0, c0)


def _source_rect(H, W):
    h = random.randint(*_SOURCE_SIZE_RANGE)
    w = random.randint(*_SOURCE_SIZE_RANGE)
    r_hi = min(_SOURCE_MAX_TOP, H - h - _SOURCE_EDGE_GAP)
    r0 = random.randint(_SOURCE_EDGE_GAP, r_hi)

    c_lo, c_hi = _SOURCE_EDGE_GAP, W - w - _SOURCE_EDGE_GAP
    center = (W - w) // 2
    c_lo = max(c_lo, center - _SOURCE_CENTER_JITTER)
    c_hi = min(c_hi, center + _SOURCE_CENTER_JITTER)
    c0 = random.randint(c_lo, c_hi)
    return (r0, c0, r0 + h - 1, c0 + w - 1)


def _choose_grouped(candidates):
    if not candidates:
        return None
    groups = {}
    for item in candidates:
        groups.setdefault(item[1], []).append(item[0])
    return random.choice(random.choice(list(groups.values())))


def _is_visible_blocker(grid, source, rect, axis, side):
    sr0, sc0, sr1, sc1 = source
    r0, c0, r1, c1 = rect
    if axis == "h":
        for r in range(max(sr0, r0), min(sr1, r1) + 1):
            if side == "left":
                if not np.any(grid[r, c1 + 1 : sc0] == _BLUE):
                    return True
            else:
                if not np.any(grid[r, sc1 + 1 : c0] == _BLUE):
                    return True
    else:
        for c in range(max(sc0, c0), min(sc1, c1) + 1):
            if side == "up":
                if not np.any(grid[r1 + 1 : sr0, c] == _BLUE):
                    return True
            else:
                if not np.any(grid[sr1 + 1 : r0, c] == _BLUE):
                    return True
    return False


def _blocker_candidates(grid, source, rects):
    H, W = grid.shape
    sr0, sc0, sr1, sc1 = source
    candidates = []

    for h in _BLOCKER_HEIGHTS:
        for w in _BLOCKER_WIDTHS:
            for r in range(max(0, sr0 - h + 1), min(sr1, H - h) + 1):
                for side, c_range in (
                    ("left", range(0, sc0 - w - _RAY_OBJECT_GAP + 1)),
                    ("right", range(sc1 + _RAY_OBJECT_GAP + 1, W - w + 1)),
                ):
                    for c in c_range:
                        rect = (r, c, r + h - 1, c + w - 1)
                        if _fits(rect, rects, H, W) and _is_visible_blocker(grid, source, rect, "h", side):
                            candidates.append((rect, ("h", side, h, w)))

            for c in range(max(0, sc0 - w + 1), min(sc1, W - w) + 1):
                for side, r_range in (
                    ("up", range(0, sr0 - h - _RAY_OBJECT_GAP + 1)),
                    ("down", range(sr1 + _RAY_OBJECT_GAP + 1, H - h + 1)),
                ):
                    for r in r_range:
                        rect = (r, c, r + h - 1, c + w - 1)
                        if _fits(rect, rects, H, W) and _is_visible_blocker(grid, source, rect, "v", side):
                            candidates.append((rect, ("v", side, h, w)))

    return candidates


def _place_blockers(grid, source, rects):
    """Place visible blue blockers; return False if any required choice fails."""
    for _ in range(random.randint(*_BLOCKER_COUNT_RANGE)):
        rect = _choose_grouped(_blocker_candidates(grid, source, rects))
        if rect is None:
            return False
        _place(grid, rect, _BLUE)
        rects.append(rect)
    return True


def _ray_mask(grid, source):
    H, W = grid.shape
    sr0, sc0, sr1, sc1 = source
    mask = np.zeros((H, W), dtype=bool)
    for r in range(sr0, sr1 + 1):
        for c in range(sc0 - 1, -1, -1):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
        for c in range(sc1 + 1, W):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
    for c in range(sc0, sc1 + 1):
        for r in range(sr0 - 1, -1, -1):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
        for r in range(sr1 + 1, H):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
    return mask


def _red_candidates(ray_mask, rects, want_path):
    H, W = ray_mask.shape
    candidates = []
    for h in _RED_HEIGHTS:
        for w in _RED_WIDTHS:
            for r in range(0, H - h + 1):
                for c in range(0, W - w + 1):
                    rect = (r, c, r + h - 1, c + w - 1)
                    if not _fits(rect, rects, H, W):
                        continue
                    in_path = bool(np.any(ray_mask[r : r + h, c : c + w]))
                    if in_path == want_path:
                        candidates.append((rect, (h, w)))
    return candidates


def _place_red_objects(grid, ray_mask, rects):
    """Place red rectangles with the preselected path/non-path role mix."""
    red_count = random.randint(*_RED_COUNT_RANGE)
    path_count = random.randint(_RED_PATH_COUNT_MIN, red_count - 1)
    red_roles = [True] * path_count + [False] * (red_count - path_count)
    random.shuffle(red_roles)
    for want_path in red_roles:
        rect = _choose_grouped(_red_candidates(ray_mask, rects, want_path))
        if rect is None:
            return False
        _place(grid, rect, _RED)
        rects.append(rect)
    return True


def _gen_attempt():
    W = random.randint(*_GRID_WIDTH_RANGE)
    grid = np.zeros((_GRID_HEIGHT, W), dtype=int)

    source = _source_rect(*grid.shape)
    rects = [source]
    _place(grid, source, _TEAL)
    if not _place_blockers(grid, source, rects):
        return None

    ray_mask = _ray_mask(grid, source)
    if not _place_red_objects(grid, ray_mask, rects):
        return None

    colors = set(map(int, np.unique(grid)))
    if colors != _REQUIRED_INPUT_COLORS or _YELLOW in colors:
        return None
    return grid


def generate_input() -> np.ndarray:
    for _ in range(_MAX_GENERATION_ATTEMPTS):
        inp = _gen_attempt()
        if inp is None:
            continue
        try:
            out = main(inp)
        except Exception:
            continue
        if out.shape == inp.shape and not np.array_equal(out, inp):
            return inp
    raise RuntimeError("failed to generate a valid 6ffe8f07 input")

def main(grid: np.ndarray) -> np.ndarray:
    """
    Mark the missing center of each plus-shaped arrangement of four two-pixel bars with yellow.

    Input structure:
    - The background is the dominant color.
    - The single foreground color forms isolated 4-connected objects, each a horizontal or vertical two-pixel bar.
    - Some bars form an implied plus sign: two horizontal bars and two vertical bars around an empty center, with a one-pixel gap between the center and each bar.

    Rule:
    - Keep the input unchanged except at implied plus-sign centers.
    - For every background pixel with foreground bars at offsets 2-3 cells left, right, above, and below, recolor that center yellow.
    - The one-pixel gaps immediately next to the center in the four cardinal directions must remain background.

    Key insight:
    - The yellow pixels are not extending a line; they identify the shared missing center where four separated two-pixel bars align as a plus sign.
    """
    g = np.asarray(grid, dtype=int)
    assert g.ndim == 2, "expected a 2D grid"
    height, width = g.shape
    assert height >= 7 and width >= 7, "grid must be large enough for the plus motif"

    bg = get_bg(g)
    foreground = colors_present(g, exclude={bg})
    assert len(foreground) == 1, "expected exactly one foreground color"
    fg = int(foreground[0])
    assert bg != Color.YELLOW and fg != Color.YELLOW, "yellow is reserved for output markers"
    _assert_two_cell_bars(g, bg, fg)

    centers = [
        (r, c)
        for r in range(3, height - 3)
        for c in range(3, width - 3)
        if _is_cross_center(g, r, c, bg, fg)
    ]
    assert centers, "expected at least one missing plus center"

    out = g.copy()
    for r, c in centers:
        out[r, c] = Color.YELLOW
    return out

# --------------- generator (att1) ---------------

# Canvas and color bounds.
GRID_SIZE_MIN = 8
GRID_SIZE_MAX_EXCLUSIVE = 21
BACKGROUND_COLOR = 8
FOREGROUND_COLOR = 1

# Plus motif placement.
PLUS_COUNT_MIN = 1
PLUS_COUNT_MAX_EXCLUSIVE = 5
CENTER_MARGIN = 3
CENTER_TRIES = 100

# Distractor bar placement.
DISTRACTOR_RATIO_MIN = 0.2
DISTRACTOR_RATIO_MAX = 0.6
DISTRACTOR_RETRY_MULTIPLIER = 20
NEW_PLUS_SCAN_RADIUS = 3

# Overall generation retries.
GENERATION_ATTEMPTS = 300
NEIGHBOR_OFFSETS = ((-1, 0), (1, 0), (0, -1), (0, 1))


def _offset_cells(r: int, c: int, offsets: tuple[tuple[int, int], ...]) -> list[tuple[int, int]]:
    return [(r + dr, c + dc) for dr, dc in offsets]


def _all_cells_bg(grid: np.ndarray, cells: list[tuple[int, int]], bg: int) -> bool:
    height, width = grid.shape
    for r, c in cells:
        if r < 0 or r >= height or c < 0 or c >= width:
            return False
        if grid[r, c] != bg:
            return False
    return True


def _cells_are_isolated(grid: np.ndarray, cells: list[tuple[int, int]], bg: int) -> bool:
    """Check that cells have no 4-neighbor foreground outside their own component."""
    height, width = grid.shape
    cell_set = set(cells)
    for r, c in cells:
        for dr, dc in NEIGHBOR_OFFSETS:
            nr, nc = r + dr, c + dc
            if (nr, nc) in cell_set:
                continue
            if 0 <= nr < height and 0 <= nc < width and grid[nr, nc] != bg:
                return False
    return True


def _place_plus_centers(grid: np.ndarray, rng: np.random.Generator, count: int, bg: int, fg: int) -> list[tuple[int, int]]:
    """Place up to count complete plus motifs and return their hidden centers."""
    height, width = grid.shape
    centers = []
    for _ in range(count):
        found = False
        for _try in range(CENTER_TRIES):
            r = int(rng.integers(CENTER_MARGIN, height - CENTER_MARGIN))
            c = int(rng.integers(CENTER_MARGIN, width - CENTER_MARGIN))
            arm_cells = _offset_cells(r, c, ARM_OFFSETS)
            gap_cells = _offset_cells(r, c, GAP_OFFSETS)
            all_cells = arm_cells + gap_cells + [(r, c)]

            if not _all_cells_bg(grid, all_cells, bg):
                continue
            if not _cells_are_isolated(grid, arm_cells, bg):
                continue

            for ar, ac in arm_cells:
                grid[ar, ac] = fg
            centers.append((r, c))
            found = True
            break

        if not found:
            break
    return centers


def _target_distractor_count(rng: np.random.Generator, plus_count: int) -> int:
    arm_bars = plus_count * 4
    ratio = rng.uniform(DISTRACTOR_RATIO_MIN, DISTRACTOR_RATIO_MAX)
    return max(1, int(round(arm_bars * ratio / (1 - ratio))))


def _candidate_centers_near_bar(bar_cells: list[tuple[int, int]], height: int, width: int) -> set[tuple[int, int]]:
    check_cells = set()
    for br, bc in bar_cells:
        for dr in range(-NEW_PLUS_SCAN_RADIUS, NEW_PLUS_SCAN_RADIUS + 1):
            for dc in range(-NEW_PLUS_SCAN_RADIUS, NEW_PLUS_SCAN_RADIUS + 1):
                cr, cc = br + dr, bc + dc
                if CENTER_MARGIN <= cr < height - CENTER_MARGIN and CENTER_MARGIN <= cc < width - CENTER_MARGIN:
                    check_cells.add((cr, cc))
    return check_cells


def _would_create_extra_plus(
    grid: np.ndarray, bar_cells: list[tuple[int, int]], centers: list[tuple[int, int]], bg: int, fg: int
) -> bool:
    height, width = grid.shape
    for cr, cc in _candidate_centers_near_bar(bar_cells, height, width):
        if (cr, cc) in centers:
            continue
        if grid[cr, cc] != bg:
            continue
        arms_ok = all(0 <= cr + dr < height and 0 <= cc + dc < width and grid[cr + dr, cc + dc] == fg
                      for dr, dc in ARM_OFFSETS)
        gaps_ok = all(0 <= cr + dr < height and 0 <= cc + dc < width and grid[cr + dr, cc + dc] == bg
                      for dr, dc in GAP_OFFSETS)
        if arms_ok and gaps_ok:
            return True
    return False


def _place_distractors(
    grid: np.ndarray, rng: np.random.Generator, target_count: int, centers: list[tuple[int, int]], bg: int, fg: int
) -> int:
    height, width = grid.shape
    placed = 0
    for _ in range(target_count * DISTRACTOR_RETRY_MULTIPLIER):
        if placed >= target_count:
            break

        orientation = rng.integers(0, 2)
        r0 = int(rng.integers(0, height))
        c0 = int(rng.integers(0, width))
        if orientation == 0:
            r1, c1 = r0, c0 + 1
        else:
            r1, c1 = r0 + 1, c0

        if r1 >= height or c1 >= width:
            continue
        if grid[r0, c0] != bg or grid[r1, c1] != bg:
            continue

        bar_cells = [(r0, c0), (r1, c1)]
        if not _cells_are_isolated(grid, bar_cells, bg):
            continue

        for r, c in bar_cells:
            grid[r, c] = fg

        if _would_create_extra_plus(grid, bar_cells, centers, bg, fg):
            for r, c in bar_cells:
                grid[r, c] = bg
            continue

        placed += 1
    return placed


def _passes_solver_oracle(grid: np.ndarray, centers: list[tuple[int, int]]) -> bool:
    try:
        out = main(grid.copy())
    except (AssertionError, Exception):
        return False

    expected = grid.copy()
    for r, c in centers:
        expected[r, c] = 4
    return np.array_equal(out, expected)


def _gen_attempt() -> np.ndarray | None:
    rng = np.random.default_rng()

    height = rng.integers(GRID_SIZE_MIN, GRID_SIZE_MAX_EXCLUSIVE)
    width = rng.integers(GRID_SIZE_MIN, GRID_SIZE_MAX_EXCLUSIVE)
    bg = BACKGROUND_COLOR
    fg = FOREGROUND_COLOR

    grid = np.full((height, width), bg, dtype=int)

    plus_count = rng.integers(PLUS_COUNT_MIN, PLUS_COUNT_MAX_EXCLUSIVE)
    if height < 2 * CENTER_MARGIN + 1 or width < 2 * CENTER_MARGIN + 1:
        return None

    centers = _place_plus_centers(grid, rng, plus_count, bg, fg)
    if len(centers) == 0:
        return None

    distractor_count = _target_distractor_count(rng, len(centers))
    placed_distractors = _place_distractors(grid, rng, distractor_count, centers, bg, fg)
    if placed_distractors < 1:
        return None

    if not _passes_solver_oracle(grid, centers):
        return None

    return grid


def generate_input() -> np.ndarray:
    for _ in range(GENERATION_ATTEMPTS):
        result = _gen_attempt()
        if result is not None:
            return result
    raise RuntimeError(f"Failed to generate valid input after {GENERATION_ATTEMPTS} attempts")
